package main

import (
	"fmt"
	"sync"
)

type HitCounter struct {
	counts map[string]int
	mu     sync.Mutex
}

func NewHitCounter() *HitCounter {
	return &HitCounter{
		counts: make(map[string]int),
	}
}

func (h *HitCounter) Record(page string) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.counts[page]++
}

func (h *HitCounter) Get(page string) int {
	h.mu.Lock()
	defer h.mu.Unlock()
	return h.counts[page]
}

func (h *HitCounter) Total() int {
	h.mu.Lock()
	defer h.mu.Unlock()
	total := 0
	for _, v := range h.counts {
		total += v
	}
	return total
}

func main() {
	counter := NewHitCounter()
	var wg sync.WaitGroup

	pages := []string{"/home", "/about", "/contact", "/api/users", "/api/orders"}

	for _, page := range pages {
		for i := 0; i < 100; i++ {
			wg.Add(1)
			go func(p string) {
				defer wg.Done()
				counter.Record(p)
			}(page)
		}
	}

	wg.Wait()
	fmt.Printf("Total hits: %d\n", counter.Total())
}
EOF

